@Serializable sealed interface TrainPilotDestination {
    // Bottom Navigation Tabok
    @Serializable data object DashboardTab : TrainPilotDestination          // Főoldal / Gyorsindítás / Aktuális heti összegzés
    @Serializable data object TemplatesTab : TrainPilotDestination          // Edzéssablonok és Gyakorlat-katalógus
    @Serializable data object HistoryTab : TrainPilotDestination            // Edzésnapló (Naptár + Lista)
    @Serializable data object AnalyticsAndSettingsTab : TrainPilotDestination // Statisztikák, PR-ok, Óra szinkron & Beállítások

    // Teljes képernyős folyamatok (Full-screen Routes)
    @Serializable data class ActiveWorkoutRoute(val workoutId: String) : TrainPilotDestination
    @Serializable data class WorkoutDetailRoute(val workoutId: String) : TrainPilotDestination
    @Serializable data class WorkoutGpsMapFullRoute(val workoutId: String) : TrainPilotDestination
    @Serializable data class TemplateEditorRoute(val templateId: String? = null) : TrainPilotDestination
    @Serializable data class ExerciseDetailHistoryRoute(val exerciseId: String) : TrainPilotDestination
    @Serializable data object WearSyncDiagnosticsRoute : TrainPilotDestination // Outbox / #193 / #202 szinkron állapot monitor
}
